def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    frames=[]
    for color in range(1,10):
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if len(pts)<8: continue
        r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
        border={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if r in (r0,r1) or c in (c0,c1)}
        if all(grid[r][c]==color for r,c in border): frames.append((color,r0,r1,c0,c1))
    # Markers are assigned to the closest frame by Manhattan distance. Fill its interior
    # on alternating checkerboard cells with the assigned marker's color.
    for frame in frames:
        color,r0,r1,c0,c1=frame
        for r,c in frame_cells(r0,r1,c0,c1):
            if r in (r0,r1) or c in (c0,c1): out[r][c]=color
    for r in range(h):
        for c in range(w):
            q=grid[r][c]
            if q==0 or any(a<=r<=b and x<=c<=y for _,a,b,x,y in frames): continue
            nearest=min((max(a-r,0,r-b)+max(x-c,0,c-y),i) for i,(_,a,b,x,y) in enumerate(frames)) if frames else None
            if nearest:
                d,i=nearest
                # Marker color designates pattern; adjacent marks in same distance layer also count.
                # Use the color of the nearest sparse mark for the whole frame pattern.
                _,a,b,x,y=frames[i]
                # Initial pattern phase from frame top-left interior.
                for rr in range(a+1,b):
                    for cc in range(x+1,y):
                        if (rr-a+cc-x)%2==0: out[rr][cc]=q
    return out

def frame_cells(r0,r1,c0,c1):
    for r in range(r0,r1+1):
        for c in range(c0,c1+1): yield r,c
