def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]; frames=[]
    # Find rectangular outlined panels from complete border rows/columns.
    for color in range(1,10):
        cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if len(cells)<8: continue
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        if r1-r0<2 or c1-c0<2: continue
        if all(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,c1+1)
               if r in (r0,r1) or c in (c0,c1)):
            frames.append((color,r0,r1,c0,c1))
    inside={(r,c) for _,r0,r1,c0,c1 in frames
            for r in range(r0,r1+1) for c in range(c0,c1+1)}
    # Marker colors are ordered by how often they occur outside panels; the largest
    # panel gets the most common marker color, and smaller panels get successive ranks.
    freq={}
    for r in range(h):
        for c in range(w):
            q=grid[r][c]
            if q and (r,c) not in inside:
                freq[q]=freq.get(q,0)+1
    palette=[q for q,_ in sorted(freq.items(),key=lambda kv:(-kv[1],kv[0]))]
    ranked=sorted(frames,key=lambda f:((f[2]-f[1]-1)*(f[4]-f[3]-1)),reverse=True)
    fill_for={frame: palette[i] for i,frame in enumerate(ranked) if i<len(palette)}
    for frame in frames:
        color,r0,r1,c0,c1=frame
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1): out[r][c]=color
        fill=fill_for.get(frame,0)
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==0: out[r][c]=fill
    return out
